    """
    Solves the Lieges of Legendre game problem.

    Uses Sprague-Grundy theorem to determine the winner.
    The game is an impartial game, so we can compute Grundy numbers
    (nim-values) for each pile and XOR them together.
    """
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    # Maximum value to compute Grundy numbers for
    max_val = 0
    for x in a:
        max_val = max(max_val, min(x, 200000))

    # Grundy value cache
    g_cache = {0: 0}

    def get_grundy(n, k):
        if n in g_cache:
            return g_cache[n]

        if n % 2 == 1:
            # Odd n: can only remove 1 cow
            g = get_grundy(n - 1, k)
        else:
            # Even n: can remove 1 cow or split
            g_opts = get_grundy(n - 1, k)
            # Split option: replace n with k piles of n/2
            half = n // 2
            split_g = get_grundy(half, k)
            if k % 2 == 1:
                # XOR of k copies = split_g (if odd) or 0 (if even)
                g_opts |= (1 << split_g) if split_g < 20 else g_opts & ~(1 << split_g)
            else:
                g_opts |= (1 << 0)

        # Compute mex
        mex = 0
        while mex in g_cache or (n - 1 in g_cache and get_grundy(n - 1, k) == mex) or \
              (n > 0):
            mex += 1

        g = mex
        g_cache[n] = g
        return g

    # Simplified approach for the given constraints
    result_xor = compute_nim_value(a, k)

    return "Kevin\n" if result_xor > 0 else "Nicky\n"

def compute_nim_value(arr, k):
    k_odd = k % 2 == 1
    xor_sum = 0

    for val in arr:
        if val == 1:
            g = 1 if k_odd else 0
        elif val == 2:
            g = 0 if k_odd else 1
        elif val % 2 == 1:
            # Odd value
            g = 1
