def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ''

    n = int(lines[0])
    if n == 0:
        return ''

    sheep = []
    for i in range(n):
        parts = lines[i + 1].split()
        if len(parts) >= 2:
            l, r = int(parts[0]), int(parts[1])
            sheep.append((l, r, i + 1))

    if not sheep:
        return ''

    # Build overlap graph - edges connect sheep with overlapping intervals
    adj = [[] for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            if sheep[i][0] <= sheep[j][1] and sheep[j][0] <= sheep[i][1]:
                adj[i].append(j)
                adj[j].append(i)

    # Find connected components
    visited = [False] * n
    components = []
    for i in range(n):
        if not visited[i]:
            comp = []
            stack = [i]
            visited[i] = True
            while stack:
                node = stack.pop()
                comp.append(node)
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)
            components.append(comp)

    # Sort each component by left endpoint and concatenate
    result = []
    for comp in components:
        comp.sort(key=lambda x: sheep[x][0])
        result.extend([sheep[x][2] for x in comp])

    return ' '.join(map(str, result))
